-- Embroidery Factory Manager — database schema
-- One owner account only. Every table is private to the logged-in owner (Row Level Security).
-- The public (publishable / anon) key can do nothing except ask whether an owner account exists.

-- ---------------------------------------------------------------------------
-- Tables (ids are text, generated by the app)
-- ---------------------------------------------------------------------------
create table if not exists public.settings (
  id integer primary key default 1 check (id = 1),
  factory_name text not null default 'My Embroidery Factory',
  updated_at timestamptz not null default now()
);

create table if not exists public.customers (
  id text primary key,
  name text not null,
  phone text,
  city text,
  notes text,
  created_at timestamptz not null default now()
);

create table if not exists public.suppliers (
  id text primary key,
  name text not null,
  phone text,
  city text,
  notes text,
  created_at timestamptz not null default now()
);

create table if not exists public.machines (
  id text primary key,
  name text not null,
  created_at timestamptz not null default now()
);

create table if not exists public.employees (
  id text primary key,
  name text not null,
  designation text not null default '',
  phone text,
  salary numeric not null default 0,
  active boolean not null default true,
  notes text,
  created_at timestamptz not null default now()
);

create table if not exists public.items (
  id text primary key,
  category text not null,
  name text not null,
  type text not null default '',
  code text not null default '',
  unit text,
  opening_qty numeric not null default 0,
  rate numeric not null default 0,
  min_qty numeric,
  created_at timestamptz not null default now()
);

create table if not exists public.orders (
  id text primary key,
  order_no text not null,
  customer_id text not null references public.customers (id) on delete restrict,
  date date not null,
  design_no text not null,
  garment text,
  reference_image text,
  quantity numeric not null default 0,
  rate numeric not null default 0,
  advance numeric not null default 0,
  delivery_date date not null,
  status text not null check (status in ('Pending', 'Designing', 'In Production', 'Completed', 'Delivered', 'Cancelled')),
  notes text,
  created_at timestamptz not null default now()
);

create table if not exists public.payments (
  id text primary key,
  customer_id text not null references public.customers (id) on delete restrict,
  order_id text references public.orders (id) on delete set null,
  date date not null,
  amount numeric not null,
  note text,
  created_at timestamptz not null default now()
);

create table if not exists public.purchases (
  id text primary key,
  date date not null,
  supplier_id text not null references public.suppliers (id) on delete restrict,
  item_id text not null references public.items (id) on delete restrict,
  qty numeric not null,
  rate numeric not null default 0,
  paid numeric not null default 0,
  bill_no text,
  notes text,
  created_at timestamptz not null default now()
);

create table if not exists public.stock (
  id text primary key,
  item_id text not null references public.items (id) on delete cascade,
  date date not null,
  type text not null check (type in ('IN', 'OUT')),
  qty numeric not null,
  note text,
  purchase_id text references public.purchases (id) on delete cascade,
  created_at timestamptz not null default now()
);

create table if not exists public.supplier_payments (
  id text primary key,
  supplier_id text not null references public.suppliers (id) on delete restrict,
  date date not null,
  amount numeric not null,
  note text,
  created_at timestamptz not null default now()
);

create table if not exists public.production (
  id text primary key,
  date date not null,
  machine_id text not null references public.machines (id) on delete restrict,
  order_id text references public.orders (id) on delete set null,
  design_no text not null default '',
  operator_id text references public.employees (id) on delete set null,
  quantity numeric not null,
  notes text,
  created_at timestamptz not null default now()
);

create table if not exists public.salaries (
  id text primary key,
  employee_id text not null references public.employees (id) on delete cascade,
  month text not null check (month ~ '^\d{4}-\d{2}$'),
  salary numeric not null default 0,
  bonus numeric not null default 0,
  advance numeric not null default 0,
  deduction numeric not null default 0,
  paid boolean not null default false,
  note text,
  created_at timestamptz not null default now()
);

create table if not exists public.expenses (
  id text primary key,
  date date not null,
  title text not null,
  category text not null default 'Other',
  amount numeric not null,
  notes text,
  created_at timestamptz not null default now()
);

-- helpful indexes for the foreign keys / common filters
create index if not exists orders_customer_idx on public.orders (customer_id);
create index if not exists orders_date_idx on public.orders (date);
create index if not exists payments_customer_idx on public.payments (customer_id);
create index if not exists payments_order_idx on public.payments (order_id);
create index if not exists purchases_supplier_idx on public.purchases (supplier_id);
create index if not exists purchases_item_idx on public.purchases (item_id);
create index if not exists stock_item_idx on public.stock (item_id);
create index if not exists stock_purchase_idx on public.stock (purchase_id);
create index if not exists supplier_payments_supplier_idx on public.supplier_payments (supplier_id);
create index if not exists production_machine_idx on public.production (machine_id);
create index if not exists production_order_idx on public.production (order_id);
create index if not exists production_operator_idx on public.production (operator_id);
create index if not exists production_date_idx on public.production (date);
create index if not exists salaries_employee_idx on public.salaries (employee_id);
create index if not exists expenses_date_idx on public.expenses (date);

-- ---------------------------------------------------------------------------
-- Security: only the logged-in owner can read or write; the public key gets nothing
-- ---------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['settings','customers','suppliers','machines','employees','items','orders','payments',
                           'purchases','stock','supplier_payments','production','salaries','expenses']
  loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, public', t);
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);
    execute format('drop policy if exists "owner full access" on public.%I', t);
    execute format(
      'create policy "owner full access" on public.%I for all to authenticated
         using ((select auth.uid()) is not null) with check ((select auth.uid()) is not null)', t);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- One owner account: the first sign-up becomes the owner, every later sign-up is refused
-- ---------------------------------------------------------------------------
create or replace function public.enforce_single_owner()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if exists (select 1 from auth.users) then
    raise exception 'This app already has an owner account. Please log in instead.';
  end if;
  return new;
end;
$$;

drop trigger if exists enforce_single_owner on auth.users;
create trigger enforce_single_owner
  before insert on auth.users
  for each row execute function public.enforce_single_owner();

revoke all on function public.enforce_single_owner() from public, anon, authenticated;

-- Lets the login screen know whether to show "Log in" or "Create owner account".
create or replace function public.owner_exists()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from auth.users);
$$;

revoke all on function public.owner_exists() from public;
grant execute on function public.owner_exists() to anon, authenticated;

-- starting row for settings
insert into public.settings (id, factory_name) values (1, 'My Embroidery Factory') on conflict (id) do nothing;
